def solve(a,b):
    prev=[0]*(len(b)+1)
    for x in a:
        cur=[0]*(len(b)+1)
        for j in range(1,len(b)+1): cur[j]=prev[j-1]+1 if x==b[j-1] else max(prev[j],cur[j-1])
        prev=cur
    return prev[-1]
